import{bV as e,aL as a,u as t,G as i}from"./chunks/framework.D_inzUUb.js";const k=JSON.parse('{"title":"Ubuntu systemd-resolved 配置自定义 DNS","description":"","frontmatter":{"title":"Ubuntu systemd-resolved 配置自定义 DNS","date":"2026-05-28T00:00:00.000Z","tags":["Ubuntu","DNS","systemd-resolved"]},"headers":[],"relativePath":"posts/202605/28-ubuntu-systemd-resolved-dns.md","filePath":"posts/202605/28-ubuntu-systemd-resolved-dns.md","lastUpdated":1780034644000}'),d={name:"posts/202605/28-ubuntu-systemd-resolved-dns.md"};function n(l,s,h,o,p,r){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="ubuntu-systemd-resolved-配置自定义-dns" tabindex="-1">Ubuntu systemd-resolved 配置自定义 DNS <a class="header-anchor" href="#ubuntu-systemd-resolved-配置自定义-dns" aria-label="Permalink to &quot;Ubuntu systemd-resolved 配置自定义 DNS&quot;">​</a></h1><p>Ubuntu 22.04+ 默认使用 <code>systemd-resolved</code> 管理 DNS，直接改 <code>/etc/resolv.conf</code> 会被覆盖。正确做法是通过 drop-in 配置文件。</p><h2 id="设置-dns-永久生效" tabindex="-1">设置 DNS（永久生效） <a class="header-anchor" href="#设置-dns-永久生效" aria-label="Permalink to &quot;设置 DNS（永久生效）&quot;">​</a></h2><p>创建配置目录：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/resolved.conf.d</span></span></code></pre></div><p>直接写入配置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[Resolve]\\nDNS=1.1.1.1 8.8.8.8\\nFallbackDNS=9.9.9.9&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/resolved.conf.d/dns.conf</span></span></code></pre></div><p>重启服务：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-resolved</span></span></code></pre></div><p>查看是否成功：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolvectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>你应该会看到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DNS Servers: 1.1.1.1 8.8.8.8</span></span></code></pre></div><h2 id="国内-dns-配置" tabindex="-1">国内 DNS 配置 <a class="header-anchor" href="#国内-dns-配置" aria-label="Permalink to &quot;国内 DNS 配置&quot;">​</a></h2><p>如果想用国内 DNS：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[Resolve]\\nDNS=223.5.5.5 119.29.29.29\\nFallbackDNS=1.1.1.1&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/resolved.conf.d/dns.conf</span></span></code></pre></div><p>常见国内公共 DNS：</p><table tabindex="0"><thead><tr><th>服务商</th><th>DNS 地址</th></tr></thead><tbody><tr><td>阿里 DNS</td><td><code>223.5.5.5</code> / <code>223.6.6.6</code></td></tr><tr><td>腾讯 DNSPod</td><td><code>119.29.29.29</code> / <code>119.28.28.28</code></td></tr><tr><td>字节跳动</td><td><code>180.184.1.1</code> / <code>180.184.2.2</code></td></tr></tbody></table><h2 id="恢复默认" tabindex="-1">恢复默认 <a class="header-anchor" href="#恢复默认" aria-label="Permalink to &quot;恢复默认&quot;">​</a></h2><p>删除配置文件即可恢复 DHCP 下发的 DNS：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/systemd/resolved.conf.d/dns.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemd-resolved</span></span></code></pre></div><h2 id="为什么不直接改-etc-resolv-conf" tabindex="-1">为什么不直接改 /etc/resolv.conf？ <a class="header-anchor" href="#为什么不直接改-etc-resolv-conf" aria-label="Permalink to &quot;为什么不直接改 /etc/resolv.conf？&quot;">​</a></h2><p><code>/etc/resolved</code> 是 <code>systemd-resolved</code> 的软链接，重启或网络变化后会被覆盖。通过 drop-in 配置文件的方式才是持久化的正确做法。</p><hr><p><strong>参考链接：</strong></p><ul><li><a href="https://www.freedesktop.org/software/systemd/man/systemd-resolved.service.html" target="_blank" rel="noreferrer">systemd-resolved 官方文档</a></li><li><a href="https://ubuntu.com/server/docs/network-configuration" target="_blank" rel="noreferrer">Ubuntu DNS 配置指南</a></li></ul>`,26)])])}const u=e(d,[["render",n]]);export{k as __pageData,u as default};
